5.1坐标变换工具5.1.1 坐标变换工具介绍1234567891011发布base_link到base_laser之间的变换:静态坐标发射器发射link和laser之间的坐标关系ros2 run tf2_ros static_transform_publisher --x 0.1 --y 0.0 --z 0.2 --roll 0.0 --pitch 0.0 --yaw 0.0 --frame-id base_link --child-frame-id base_laser发布base_laser到wall_point之间的变换: 发布laser到wall之间的坐标关系ros2 run tf2_ros static_transform_publisher --x 0.3 --y 0.0 --z 0.0 --roll 0.0 --pitch 0.0 --yaw 0.0 --frame-id base_laser --child-frame-id wall_point查询base_link到wall_point之间的关系:ros2 run tf2_ros tf2_echo base_link wall_point 通过命令行使用TF｜3D可视化 1234sudo add-apt-repository ppa:joseluisblancoc/mrpt//add-apt-repository：这是 Ubuntu 系统中用于添加 APT 软件源的工具。sudo apt install mrpt-apps3d-rotation-converter 5.1.2 TF原理坐标关系发布———利用ros的通信机制实现的 通过 ros2 topic list可以查询到一个tf_static话题， ros2 topic info /tf_static查看话题信息， 使用ros2 interface show tf2_msgs/msg/TFMessage 查看消息接口的定义。 最后通过ros2 topic echo /tf_static订阅话题，可输出link到laser和laser到wall的坐标关系，通过计算可得到link和wall之间的坐标关系。 5.2 TF手眼坐标变换5.2.1 发布静态TF![image-20250729101645145](/Users/zhou/Library/Application Support/typora-user-images/image-20250729101645145.png) 使用静态tf发布摄像机和机械臂之间的静态关系。 1234567891011121314151617181920212223242526272829303132333435363738394041424344451.创建功能包ros2 pkg create --build-type ament_python --dependencies rclpy geometry_msgs tf_ros tf_transformations --license Apache-2.0 demo_python_tf2.代码编写import rclpyfrom rclpy.node import Nodefrom tf2_ros import StaticTransformBroadcasterfrom geometry_msgs.msg import TransformStampedfrom tf_transformations import quaternion_from_eulerimport mathclass StaticTFBroadcaster(Node): def __init__(self,node_name): super().__init__(node_name) self.static_broadcaster = StaticTransformBroadcaster(self) self.publish_static_tf() def publish_static_tf(self): &quot;&quot;&quot; 发布从base link 到creame link的静态tf &quot;&quot;&quot; transform = TransformStamped() transform.header.frame_id = 'base_link' transform.child_frame_id = 'creame_link' transform.header.stamp = self.get_clock().now().to_msg() transform.transform.translation.x = 0.5 transform.transform.translation.y = 0.3 transform.transform.translation.z = 0.6 &quot;&quot;&quot;欧拉角转四元数 quaternion=[x,y,z,w]&quot;&quot;&quot; quaternion = quaternion_from_euler(math.radians(180),0,0) transform.transform.rotation.x = quaternion[0] transform.transform.rotation.y = quaternion[1] transform.transform.rotation.z = quaternion[2] transform.transform.rotation.w = quaternion[3] &quot;&quot;&quot;发布坐标&quot;&quot;&quot; self.static_broadcaster.sendTransform(transform) self.get_logger().info(f'publish static tf:
{transform}
')def main(): rclpy.init() node = StaticTFBroadcaster('static_tf_broadcaster') rclpy.spin(node) rclpy.shutdown() 3.查看点位置信息ros2 run tf2_ros tf2_echo base_link creame_link 5.2.1 发布动态TF发布动态tf，不停的发布摄像机和瓶子之间的关系。 123456789101112131415161718192021222324252627282930313233343536373839import rclpyfrom rclpy.node import Nodefrom tf2_ros import TransformBroadcasterfrom geometry_msgs.msg import TransformStampedfrom tf_transformations import quaternion_from_eulerclass StaticTFBroadcaster(Node): def __init__(self,node_name): super().__init__(node_name) self.broadcaster = TransformBroadcaster(self) self.timer_ = self.create_timer(0.1,self.publish_tf) def publish_tf(self): &quot;&quot;&quot; 发布从base link 到creame link的静态tf &quot;&quot;&quot; transform = TransformStamped() transform.header.frame_id = 'creame_link' transform.child_frame_id = 'bottle_link' transform.header.stamp = self.get_clock().now().to_msg() transform.transform.translation.x = 0.2 transform.transform.translation.y = 0.3 transform.transform.translation.z = 0.5 &quot;&quot;&quot;欧拉角转四元数 quaternion=[x,y,z,w]&quot;&quot;&quot; quaternion = quaternion_from_euler(0,0,0) transform.transform.rotation.x = quaternion[0] transform.transform.rotation.y = quaternion[1] transform.transform.rotation.z = quaternion[2] transform.transform.rotation.w = quaternion[3] &quot;&quot;&quot;发布坐标&quot;&quot;&quot; self.broadcaster.sendTransform(transform) self.get_logger().info(f'publish dynamic tf:
{transform}
')def main(): rclpy.init() node = StaticTFBroadcaster('dynamic_tf_broadcaster') rclpy.spin(node) rclpy.shutdown() 5.2.3 python查询tf关系订阅tf以及tf_static话题，收集所有的坐标信息，将信息放置到缓冲区，进行计算。 1234567891011121314151617181920212223242526272829303132333435363738import rclpyfrom rclpy.node import Nodeimport rclpy.timefrom tf2_ros import TransformListener,Bufferfrom tf_transformations import euler_from_quaternionclass TFListener(Node): def __init__(self,node_name): super().__init__(node_name) self.buffer_= Buffer() self.listener_ = TransformListener(self.buffer_,self) self.timer_ = self.create_timer(1,self.get_tranformation) def get_tranformation(self): try: result = self.buffer_.lookup_transform('base_link','creame_link', rclpy.time.Time(seconds=0.0), rclpy.time.Duration(seconds=1) ) transform = result.transform self.get_logger().info(f'平移：{transform.translation}') self.get_logger().info(f'旋转：{transform.rotation}') euler_ = euler_from_quaternion([ transform.rotation.x, transform.rotation.y, transform.rotation.z, transform.rotation.w, ]) self.get_logger().info(f'旋转RPY：{euler_}') except Exception as e: self.get_logger().warn(f'报错信息：{str(e)}')def main(): rclpy.init() node = TFListener('listener_tf') rclpy.spin(node) rclpy.shutdown() 5.3可视化工具5.3.1 rqt12345sudo apt install ros-$ROS_DISTRO-rqt-tf-tree -y需要删除配置文件，删除配置文件之后系统才会扫描系统中的rqt插件。rm -rf ~/.config/ros.org/rqt_gui.ini终端输入rqt即可以唤起rqt窗口可实时查看tf关系 5.3.2 rviz2在终端输入rviz2即可唤起窗口。 5.3.3 数据记录工具ros2 bag121.使用指令ros2 bag record ...可记录执行2.使用指令ros2 bag play ...file-name... 可回放执行
